<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>UbuntuLOS — Desktop</title>
<style>
  * { box-sizing: border-box; }
  html, body { height: 100%; }
  body {
    margin: 0; overflow: hidden;
    font-family: "Ubuntu", "Cantarell", "Segoe UI", -apple-system, "Noto Sans", sans-serif;
    -webkit-font-smoothing: antialiased;
    user-select: none;
    background: #111;
  }

  /* ===================== Desktop / wallpaper ===================== */
  #desktop {
    position: fixed; inset: 0; width: 100vw; height: 100vh; overflow: hidden;
    background:
      radial-gradient(1100px 760px at 78% 16%, rgba(233, 84, 32, .40), rgba(233, 84, 32, 0) 62%),
      radial-gradient(950px 720px at 10% 90%, rgba(119, 33, 111, .65), rgba(119, 33, 111, 0) 60%),
      radial-gradient(720px 520px at 45% 45%, rgba(255, 255, 255, .05), rgba(255, 255, 255, 0) 70%),
      linear-gradient(140deg, #170a20 0%, #2b1130 38%, #4a1c40 68%, #77216f 100%);
  }

  /* ===================== Top bar ===================== */
  #topbar {
    position: absolute; top: 0; left: 0; right: 0; height: 32px; z-index: 1000;
    display: flex; align-items: center; justify-content: space-between;
    padding: 0 14px; font-size: 13px; color: #eee;
    background: rgba(14, 14, 14, .78);
    backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
    box-shadow: 0 1px 0 rgba(255, 255, 255, .06);
  }
  .tb-left { display: flex; align-items: center; gap: 16px; min-width: 220px; }
  .tb-activities { font-weight: 700; }
  #tb-app { opacity: .85; }
  .tb-center { position: absolute; left: 50%; transform: translateX(-50%); font-weight: 500; letter-spacing: .3px; }
  .tb-right { display: flex; align-items: center; gap: 10px; min-width: 220px; justify-content: flex-end; font-size: 12px; opacity: .9; }

  /* ===================== Dock / taskbar ===================== */
  #taskbar {
    position: absolute; left: 0; top: 32px; bottom: 0; width: 64px; z-index: 1000;
    display: flex; flex-direction: column; align-items: center;
    padding: 12px 0; gap: 12px;
    background: rgba(18, 18, 18, .66);
    backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
    border-right: 1px solid rgba(255, 255, 255, .06);
  }
  .launcher {
    position: relative; width: 46px; height: 46px; border: none; border-radius: 12px;
    background: rgba(255, 255, 255, .07); cursor: pointer;
    font-size: 23px; line-height: 1;
    display: flex; align-items: center; justify-content: center;
    transition: background .12s ease, transform .12s ease;
  }
  .launcher:hover { background: rgba(255, 255, 255, .17); }
  .launcher:active { transform: scale(.93); }
  .launcher.running::before {
    content: ''; position: absolute; left: -9px; top: 50%; transform: translateY(-50%);
    width: 4px; height: 22px; border-radius: 2px; background: #E95420;
  }

  /* ===================== Desktop icon ===================== */
  .desk-icon {
    position: absolute; left: 88px; top: 56px; width: 92px; z-index: 1;
    padding: 8px 4px; border-radius: 8px; text-align: center; color: #fff; cursor: default;
  }
  .desk-icon .di-img { font-size: 40px; display: block; filter: drop-shadow(0 2px 3px rgba(0, 0, 0, .5)); }
  .desk-icon .di-label { display: block; margin-top: 4px; font-size: 12px; text-shadow: 0 1px 2px rgba(0, 0, 0, .85); }
  .desk-icon.sel { background: rgba(233, 84, 32, .35); }

  /* ===================== Windows ===================== */
  .window {
    position: absolute; display: none; flex-direction: column;
    min-width: 360px; min-height: 240px;
    background: #282828; border: 1px solid rgba(255, 255, 255, .09); border-radius: 12px;
    box-shadow: 0 24px 70px rgba(0, 0, 0, .6), 0 4px 16px rgba(0, 0, 0, .4);
    overflow: hidden; resize: both; z-index: 10;
  }
  .window.open { display: flex; animation: pop .14s ease-out; }
  @keyframes pop { from { opacity: 0; transform: scale(.97); } to { opacity: 1; transform: scale(1); } }
  .window.maximized {
    left: 64px !important; top: 32px !important;
    width: calc(100vw - 64px) !important; height: calc(100vh - 32px) !important;
    border-radius: 0; resize: none;
  }
  .win-titlebar {
    height: 40px; flex: none; display: flex; align-items: center; justify-content: space-between;
    padding: 0 8px 0 14px; background: linear-gradient(#3d3d3d, #343434);
    border-bottom: 1px solid rgba(0, 0, 0, .45); cursor: grab;
  }
  .win-titlebar:active { cursor: grabbing; }
  .win-title { font-size: 13px; font-weight: 600; color: #f0f0f0; letter-spacing: .2px; }
  .win-controls { display: flex; gap: 8px; }
  .win-btn {
    width: 18px; height: 18px; border-radius: 50%; border: none; padding: 0;
    background: #4d4d4d; position: relative; cursor: pointer; flex: none;
    font-size: 12px; line-height: 18px; text-align: center; color: transparent;
    transition: background .1s ease, color .1s ease;
  }
  .win-titlebar:hover .win-btn { color: rgba(255, 255, 255, .92); }
  .win-close:hover { background: #E95420; color: #fff; }
  .win-min:hover, .win-max:hover { background: #8a8a8a; color: #111; }
  .win-close::before { content: '×'; }
  .win-min::before { content: '–'; }
  .win-max::before { content: '+'; }

  /* ===================== Files app ===================== */
  .files-toolbar {
    flex: none; display: flex; align-items: center; gap: 8px;
    padding: 8px 10px; background: #2f2f2f; border-bottom: 1px solid rgba(0, 0, 0, .4);
  }
  #files-up {
    height: 30px; padding: 0 12px; cursor: pointer;
    border: 1px solid rgba(255, 255, 255, .12); border-radius: 7px;
    background: #3c3c3c; color: #eee; font-size: 13px;
  }
  #files-up:hover { background: #4b4b4b; }
  #files-path {
    flex: 1; height: 30px; display: flex; align-items: center; padding: 0 12px;
    background: #1b1b1b; border: 1px solid rgba(255, 255, 255, .08); border-radius: 7px;
    color: #e6e6e6; font-family: ui-monospace, "Ubuntu Mono", Consolas, monospace; font-size: 13px;
    overflow: hidden; white-space: nowrap;
  }
  #files-list {
    flex: 1; overflow: auto; padding: 12px;
    display: grid; grid-template-columns: repeat(auto-fill, minmax(88px, 1fr));
    gap: 4px; align-content: start; background: #242424;
  }
  .fs-item {
    display: flex; flex-direction: column; align-items: center; gap: 5px;
    padding: 10px 6px; border-radius: 9px; border: 1px solid transparent;
    color: #eaeaea; font-size: 12px; text-align: center; word-break: break-word; cursor: default;
  }
  .fs-item::before { font-size: 36px; line-height: 1; filter: drop-shadow(0 2px 2px rgba(0, 0, 0, .4)); }
  .fs-item.dir::before { content: "\1F4C1"; }
  .fs-item.file::before { content: "\1F4C4"; }
  .fs-item:hover { background: rgba(255, 255, 255, .07); }
  .fs-item.selected { background: rgba(233, 84, 32, .32); border-color: rgba(233, 84, 32, .65); }
  #files-status {
    flex: none; padding: 5px 14px; font-size: 11px; color: #9a9a9a;
    background: #2a2a2a; border-top: 1px solid rgba(0, 0, 0, .4);
  }

  /* ===================== Notepad app ===================== */
  #tabs {
    flex: none; display: flex; align-items: stretch; height: 36px;
    background: #202020; overflow-x: auto; overflow-y: hidden; scrollbar-width: none;
  }
  #tabs::-webkit-scrollbar { display: none; }
  .tab {
    flex: none; display: flex; align-items: center; gap: 10px;
    padding: 0 8px 0 14px; max-width: 190px;
    background: #282828; color: #bdbdbd; font-size: 12.5px;
    border-right: 1px solid #191919; box-shadow: inset 0 0 0 transparent; cursor: default;
  }
  .tab.active { background: #1e1e1e; color: #fff; box-shadow: inset 0 2px 0 #E95420; }
  .tab-label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .tab-close { position: relative; width: 14px; height: 14px; border-radius: 50%; flex: none; opacity: .55; }
  .tab-close:hover { opacity: 1; background: rgba(255, 255, 255, .18); }
  .tab-close::before, .tab-close::after {
    content: ''; position: absolute; left: 6px; top: 2px; width: 2px; height: 10px;
    background: #ccc; border-radius: 1px;
  }
  .tab-close::before { transform: rotate(45deg); }
  .tab-close::after { transform: rotate(-45deg); }
  #new-tab {
    flex: none; width: 36px; border: none; cursor: pointer;
    background: transparent; color: #cfcfcf; font-size: 18px; line-height: 1;
  }
  #new-tab:hover { background: rgba(255, 255, 255, .09); color: #fff; }
  #editor {
    flex: 1; width: 100%; border: none; outline: none; resize: none;
    background: #1e1e1e; color: #f5f5f5; padding: 14px 16px;
    font-family: ui-monospace, "Ubuntu Mono", "Cascadia Mono", Consolas, monospace;
    font-size: 13.5px; line-height: 1.55; user-select: text; caret-color: #E95420;
  }

  ::-webkit-scrollbar { width: 10px; height: 10px; }
  ::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, .18); border-radius: 5px; border: 2px solid transparent; background-clip: content-box; }
  ::-webkit-scrollbar-thumb:hover { background: rgba(255, 255, 255, .3); border: 2px solid transparent; background-clip: content-box; }
  ::-webkit-scrollbar-corner { background: transparent; }
</style>
</head>
<body>

<div id="desktop">

