<script>
(function () {
  'use strict';

  var filesWin = document.getElementById('files-window');
  var notepadWin = document.getElementById('notepad-window');
  var tbApp = document.getElementById('tb-app');

  /* ==================== Window manager ==================== */
  var zTop = 10;

  function bringToFront(win) {
    zTop += 1;
    win.style.zIndex = zTop;
  }

  function updateDock() {
    document.getElementById('open-files').classList.toggle('running', filesWin.classList.contains('open'));
    document.getElementById('open-notepad').classList.toggle('running', notepadWin.classList.contains('open'));
  }

  function showWindow(win) {
    win.classList.add('open');
    bringToFront(win);
    tbApp.textContent = win.querySelector('.win-title').textContent;
    updateDock();
  }

  function hideWindow(win) {
    win.classList.remove('open');
    var anyOpen = document.querySelector('.window.open');
    tbApp.textContent = anyOpen ? anyOpen.querySelector('.win-title').textContent : 'Desktop';
    updateDock();
  }

  Array.prototype.forEach.call(document.querySelectorAll('.window'), function (win) {
    var bar = win.querySelector('.win-titlebar');

    win.addEventListener('mousedown', function () {
      bringToFront(win);
      tbApp.textContent = win.querySelector('.win-title').textContent;
    });

    win.querySelector('.win-close').addEventListener('click', function () { hideWindow(win); });
    win.querySelector('.win-min').addEventListener('click', function () { hideWindow(win); });
    win.querySelector('.win-max').addEventListener('click', function () { win.classList.toggle('maximized'); });

    bar.addEventListener('dblclick', function (e) {
      if (e.target.closest('.win-btn')) return;
      win.classList.toggle('maximized');
    });

    bar.addEventListener('mousedown', function (e) {
      if (e.target.closest('.win-btn') || win.classList.contains('maximized')) return;
      e.preventDefault();
      var rect = win.getBoundingClientRect();
      var offX = e.clientX - rect.left;
      var offY = e.clientY - rect.top;
      function onMove(ev) {
        var x = Math.max(64, Math.min(ev.clientX - offX, window.innerWidth - 90));
        var y = Math.max(32, Math.min(ev.clientY - offY, window.innerHeight - 48));
        win.style.left = x + 'px';
        win.style.top = y + 'px';
      }
      function onUp() {
        document.removeEventListener('mousemove', onMove);
        document.removeEventListener('mouseup', onUp);
      }
      document.addEventListener('mousemove', onMove);
      document.addEventListener('mouseup', onUp);
    });
  });

  /* ==================== Files app ==================== */
  var FS = { type: 'dir', children: {
    bin: { type: 'dir', children: {
      bash:  { type: 'file', content: 'GNU bash, version 5.2.15(1)-release (x86_64-pc-linux-gnu)\nThis is a binary executable.' },
      cat:   { type: 'file', content: 'cat (GNU coreutils) 9.4 - concatenate files and print on the standard output.' },
      echo:  { type: 'file', content: 'echo (GNU coreutils) 9.4 - display a line of text.' },
      ls:    { type: 'file', content: 'ls (GNU coreutils) 9.4 - list directory contents.' },
      mkdir: { type: 'file', content: 'mkdir (GNU coreutils) 9.4 - make directories.' },
      sh:    { type: 'file', content: '#!/bin/dash\n# POSIX shell, symlink -> dash' }
    }},
    etc: { type: 'dir', children: {
      fstab:        { type: 'file', content: '# /etc/fstab: static file system information.\nUUID=51f7c2a1-9d3b  /  ext4  errors=remount-ro  0  1' },
      hostname:     { type: 'file', content: 'ubuntulos' },
      hosts:        { type: 'file', content: '127.0.0.1\tlocalhost\n127.0.1.1\tubuntulos\n\n::1\tip6-localhost ip6-loopback' },
      'os-release': { type: 'file', content: 'PRETTY_NAME="UbuntuLOS 24.04 LTS"\nNAME="UbuntuLOS"\nVERSION_ID="24.04"\nID=ubuntu\nID_LIKE=debian' },
      timezone:     { type: 'file', content: 'Etc/UTC' }
    }},
    home: { type: 'dir', children: {
      user: { type: 'dir', children: {
        Documents: { type: 'dir', children: {
          'notes.txt':  { type: 'file', content: 'Groceries:\n- coffee\n- oat milk\n- pasta\n\nIdeas:\n- build a fake desktop in one HTML file' },
          'todo.txt':   { type: 'file', content: 'TODO\n====\n[x] water the plants\n[ ] file taxes\n[ ] learn awk' },
          'report.odt': { type: 'file', content: '(OpenDocument Text - open with LibreOffice Writer)' }
        }},
        Downloads: { type: 'dir', children: {
          'setup.sh':                     { type: 'file', content: '#!/bin/sh\nset -e\necho "Setting things up..."\nsudo apt update && sudo apt upgrade -y' },
          'ubuntu-24.04-desktop-amd64.iso': { type: 'file', content: '(disk image, 5.7 GB)' },
          'wallpaper.png':                { type: 'file', content: '(PNG image, 3840 x 2160)' }
        }},
        Pictures: { type: 'dir', children: {
          'screenshot.png': { type: 'file', content: '(PNG image, 1920 x 1080)' },
          'vacation.jpg':   { type: 'file', content: '(JPEG image, 4032 x 3024)' }
        }},
        '.bashrc':     { type: 'file', content: '# ~/.bashrc\nalias ll="ls -alF"\nexport PS1="\\u@\\h:\\w\\$ "' },
        'readme.txt':  { type: 'file', content: 'Welcome to UbuntuLOS!\n\nDouble-click a folder to open it.\nDouble-click a file to view it in Notepad.' }
      }}
    }},
    opt:  { type: 'dir', children: {} },
    root: { type: 'dir', children: {} },
    tmp:  { type: 'dir', children: {} },
    usr: { type: 'dir', children: {
      bin: { type: 'dir', children: {
        gcc:     { type: 'file', content: 'gcc (Ubuntu 13.2.0-4ubuntu3) 13.2.0' },
        git:     { type: 'file', content: 'git version 2.43.0' },
        python3: { type: 'file', content: 'Python 3.12.3' }
      }},
      lib: { type: 'dir', children: {
        'libc.so.6': { type: 'file', content: 'GNU C Library (Ubuntu GLIBC 2.39) stable release version 2.39.' },
        'libm.so.6': { type: 'file', content: 'GNU C Library math library.' }
      }},
      share: { type: 'dir', children: {
        doc:   { type: 'dir', children: {} },
        fonts: { type: 'dir', children: {} },
        icons: { type: 'dir', children: {} }
      }}
    }},
    var: { type: 'dir', children: {
      cache: { type: 'dir', children: {
        apt: { type: 'dir', children: {} }
      }},
      log: { type: 'dir', children: {
        'auth.log': { type: 'file', content: 'Jun 21 14:02:11 ubuntulos sshd[812]: Server listening on 0.0.0.0 port 22.' },
        'dpkg.log': { type: 'file', content: '2025-06-21 14:01:03 status installed bash:amd64 5.2.15-2ubuntu1' },
        syslog:     { type: 'file', content: 'Jun 21 14:03:12 ubuntulos systemd[1]: Started Daily apt download activities.' }
      }},
      tmp: { type: 'dir', children: {} }
    }}
  }};

  var cwd = [];
  var filesPath = document.getElementById('files-path');
  var filesList = document.getElementById('files-list');
  var filesStatus = document.getElementById('files-status');
  var filesUp = document.getElementById('files-up');

  function nodeAt(parts) {
    var node = FS;
    for (var i = 0; i < parts.length; i++) node = node.children[parts[i]];
    return node;
  }

  function pathString() {
    return cwd.length ? '/' + cwd.join('/') : '/';
  }

  function renderFiles() {
    var node = nodeAt(cwd);
    var kids = node.children || {};
    filesPath.textContent = pathString();
    filesPath.title = pathString();
    filesList.innerHTML = '';

    var names = Object.keys(kids).sort(function (a, b) {
      var ta = kids[a].type, tb = kids[b].type;
      if (ta !== tb) return ta === 'dir' ? -1 : 1;
      return a.localeCompare(b);
    });

    names.forEach(function (name) {
      var child = kids[name];
      var item = document.createElement('div');
      item.className = 'fs-item ' + (child.type === 'dir' ? 'dir' : 'file');
      item.textContent = name;
      item.title = name;
      item.addEventListener('click', function () {
        Array.prototype.forEach.call(filesList.querySelectorAll('.fs-item'), function (el) {
          el.classList.remove('selected');
        });
        item.classList.add('selected');
      });
      item.addEventListener('dblclick', function () {
        if (child.type === 'dir') {
          cwd.push(name);
          renderFiles();
        } else {
          openFileInNotepad(name, child.content || '');
        }
      });
      filesList.appendChild(item);
    });

    filesStatus.textContent = names.length
      ? names.length + ' item' + (names.length > 1 ? 's' : '')
      : 'Empty folder';
  }

  filesUp.addEventListener('click', function () {
    if (cwd.length) {
      cwd.pop();
      renderFiles();
    }
  });

  /* ==================== Notepad app ==================== */
  var LS_KEY = 'ubuntulos-notepad-v1';
  var tabsEl = document.getElementById('tabs');
  var newTabBtn = document.getElementById('new-tab');
  var editor = document.getElementById('editor');

  function defaultState() {
    return { tabs: [{ id: 1, name: 'Untitled 1', content: '' }], activeId: 1, counter: 1 };
  }

  function loadState() {
    try {
      var raw = localStorage.getItem(LS_KEY);
      if (!raw) return defaultState();
      var s = JSON.parse(raw);
      if (!s || !Array.isArray(s.tabs) || !s.tabs.length) return defaultState();
      if (!s.tabs.some(function (t) { return t.id === s.activeId; })) s.activeId = s.tabs[0].id;
      if (typeof s.counter !== 'number') s.counter = s.tabs.length;
      return s;
    } catch (e) {
      return defaultState();
    }
  }

  var state = loadState();

  function save() {
    try { localStorage.setItem(LS_KEY, JSON.stringify(state)); } catch (e) { /* storage unavailable */ }
  }

  function activeTab() {
    return state.tabs.find(function (t) { return t.id === state.activeId; }) || null;
  }

  function renderTabs() {
    Array.prototype.forEach.call(tabsEl.querySelectorAll('.tab'), function (el) { el.remove(); });
    state.tabs.forEach(function (t) {
      var el = document.createElement('div');
      el.className = 'tab' + (t.id === state.activeId ? ' active' : '');
      el.dataset.id = t.id;
      var label = document.createElement('span');
      label.className = 'tab-label';
      label.textContent = t.name;
      var close = document.createElement('span');
      close.className = 'tab-close';
      close.title = 'Close tab';
      el.appendChild(label);
      el.appendChild(close);
      tabsEl.insertBefore(el, newTabBtn);
    });
    var cur = activeTab();
    editor.value = cur ? cur.content : '';
  }

  function newTab(name, content) {
    state.counter += 1;
    var t = { id: state.counter, name: name || ('Untitled ' + state.counter), content: content || '' };
    state.tabs.push(t);
    state.activeId = t.id;
    save();
    renderTabs();
  }

  function activateTab(id) {
    if (state.activeId === id) { renderTabs(); return; }
    state.activeId = id;
    save();
    renderTabs();
  }

  function closeTab(id) {
    var i = state.tabs.findIndex(function (t) { return t.id === id; });
    if (i < 0) return;
    state.tabs.splice(i, 1);
    if (!state.tabs.length) {
      state.counter += 1;
      state.tabs.push({ id: state.counter, name: 'Untitled ' + state.counter, content: '' });
    }
    if (!state.tabs.some(function (t) { return t.id === state.activeId; })) {
      state.activeId = state.tabs[Math.max(0, i - 1)].id;
    }
    save();
